/* PART NAMES — what each gallery photo actually shows.
 *
 * Keyed by file name, so this survives assets/gallery/manifest.js being
 * regenerated by tools/build-gallery.py on every deploy. Never put these
 * strings in that file: it carries a "do not edit by hand" banner and is
 * rewritten from the folder contents each time.
 *
 * These become the alt text on the homepage conveyor belt and on the
 * gallery grid and lightbox. Alt text is the only text a photo of a
 * sprocket contributes to search - without it Google Images has nothing
 * to read, and a buyer searching "gun metal bush" cannot land on 13.jpg.
 *
 * Two rules when editing:
 *   1. Describe what is genuinely in the frame. Alt text that names parts
 *      the photo does not show is hidden-keyword spam, and Google treats
 *      it as such.
 *   2. Write the phrase a buyer would type - "rotary air lock valve",
 *      not "valve assembly ref. 7". The part's trade name is the whole
 *      point of the line.
 *   3. No double quotes in the text. These strings are dropped straight
 *      into an alt="..." attribute by the belt and grid renderers, and a
 *      quote would close the attribute early. Use mm, inches or a dash.
 *
 * Adding a photo: drop it in assets/gallery/ and add a line here. A file
 * with no entry falls back to the company name, so a missing line costs
 * search visibility but never breaks the page.
 */
window.PART_NAMES = {
    '1.jpg':  'Solvent extractor machine parts — drum shafts, rotary valve, sprockets and extractor rails manufactured by Lohshree Engineers',
    '2.jpg':  'Redler conveyor drive shaft assembly with sprockets and chain wheel',
    '3.jpg':  'Extractor drum shafts with sprockets, counter flanges and mechanical seal housings',
    '4.jpg':  'Mechanical seals for solvent extraction plant rotary valves, three sizes',
    '5.jpg':  'Cast bearing housings for solvent extractor shafts, two sizes',
    '6.jpg':  'Square type rotary air lock valve with gearbox drive and sprockets',
    '7.jpg':  'Rotary air lock valve with pillow block bearing and square flange',
    '8.jpg':  'Rotary air lock valves in stainless steel and mild steel with geared drive',
    '9.jpg':  'Stainless steel square type rotary valves, bush type and mechanical seal',
    '10.jpg': 'Mild steel rotary valves, round and square inlet types',
    '11.jpg': 'Sight glass assemblies, flexible hoses and spool pieces for solvent extraction plants',
    '12.jpg': 'Extractor rails, sight glass assembly and aluminium manhole cover',
    '13.jpg': 'Gun metal bushes and bronze sleeves in all sizes',
    '14.jpg': 'Sprockets for Redler and bulk flow conveyors with chain pins',
    '15.jpg': 'Stainless steel drum shafts with sprockets for solvent extractors',
    '16.jpg': 'Scraper shaft rotor assembly with stainless steel blades',
    '17.jpg': 'Tension shaft tightening arrangement with gun metal bush',
    '18.jpg': 'Bulk flow conveyor flights and Redler conveyor slats',
    '19.jpg': 'Flanged bearing housing pedestal for extractor drive shaft',
    '20.jpg': 'Ejector assemblies and shaft assemblies with mechanical seals',
    '21.jpg': 'Scraper blades, gun metal studs, Belleville washers and ejector nozzle',
    '22.jpg': 'Jet cleaner assemblies for solvent extractor cleaning',
    '23.jpg': 'Stainless steel ejector set with nozzle, studs and scraper blades',
    '24.jpg': 'Jet cleaner spray pipe assemblies in stainless steel and mild steel',
    '25.jpg': 'Mild steel rotary air lock valves in batch production',
    '26.jpg': 'M.S. and EN8 extractor rails and monorails in all sizes',
    '27.jpg': 'Stainless steel cone hoppers and transition pieces',
    '28.jpg': 'Stainless steel angle and flat bar sections',
    '29.jpg': 'Segmented chain wheels and sprockets for Redler conveyors',
};

/* Looks up a photo's description. Takes either a file name ("13.jpg") or a
 * path ending in one ("assets/gallery/thumbs/13.jpg"), so callers can pass
 * whichever they already hold. Falls back to the company name rather than
 * an empty string - a photo with no alt at all is worse for search than a
 * generic one, and a screen reader announces nothing for it.
 */
window.partName = function (file) {
    if (!file) return 'Lohshree Engineers';
    const name = decodeURIComponent(String(file)).split('/').pop();
    return window.PART_NAMES[name] || 'Lohshree Engineers';
};
